ROOTS={'friday_chat':ROOT/'packages/friday-chat/src/friday_chat','friday_commands':ROOT/'packages/friday-commands/src/friday_commands','friday_cli':ROOT/'packages/friday-cli/src/friday_cli'}
BEFORE={str(p.resolve()):hashlib.sha256(p.read_bytes()).hexdigest() for root in ROOTS.values() for p in root.rglob('*.py')}
STATE={'before':BEFORE,'finish':{},'after':{},'mismatches':[]}

def snapshot():
    result={};errors=[]
    for name,module in tuple(sys.modules.items()):
        package=name.split('.')[0]
        if package not in ROOTS or module is None:continue
        paths=([module.__file__] if getattr(module,'__file__',None) else [])+list(getattr(module,'__path__',()))
        if not paths:errors.append('missing origin: '+name)
        files=[]
        for raw in paths:
            path=Path(raw).resolve()
            if not path.is_relative_to(ROOTS[package]):errors.append('noncanonical origin: '+name+' '+str(path))
            row={'path':str(path)}
            if path.is_file():
                row['sha256']=hashlib.sha256(path.read_bytes()).hexdigest()
                if BEFORE.get(str(path))!=row['sha256']:errors.append('source drift: '+name)
            files.append(row)
        result[name]=files
    return result,errors

def pytest_sessionfinish(session,exitstatus):
    STATE['finish'],errors=snapshot();STATE['mismatches']+=errors
    STATE['test_exit']=exitstatus
    if errors:session.exitstatus=1
    REPORT.write_text(json.dumps(STATE,indent=2)+'\n')

def finished():
    STATE['after'],errors=snapshot();STATE['mismatches']+=errors
    if STATE['after']!=STATE['finish']:STATE['mismatches'].append('loaded origins changed after session finish')
    REPORT.write_text(json.dumps(STATE,indent=2)+'\n')

atexit.register(finished)

"""Extend the historical Python-open guard with SQLite path auditing."""

from __future__ import annotations

import os
import sqlite3
import sys
from pathlib import Path
from urllib.parse import unquote, urlsplit


def install() -> None:
    roots = (
        (Path.home() / ".friday").resolve(),
        (Path(os.environ["REVIEW_REPO"]) / ".friday").resolve(),
    )

    def protected(value: object) -> bool:
        if not isinstance(value, (str, bytes, os.PathLike)):
            return False
        text = os.fsdecode(value)
        if text.startswith("file:"):
            text = unquote(urlsplit(text).path)
        if text in ("", ":memory:"):
            return False
        path = Path(text).expanduser().resolve()
        if sys.platform == "darwin":
            path = Path(str(path).casefold())
            compared_roots = [Path(str(root).casefold()) for root in roots]
        else:
            compared_roots = roots
        return any(path == root or path.is_relative_to(root) for root in compared_roots)

    def audit(event: str, arguments: tuple[object, ...]) -> None:
        if event == "sqlite3.connect" and protected(arguments[0]):
            raise RuntimeError("Pilot store guard blocked protected .friday path")
        # Relative os.open audit events omit dir_fd; the historical hook handles
        # ordinary relative opens. Avoid guessing their base directory here.
        if (
            event == "open"
            and isinstance(arguments[0], (str, bytes, os.PathLike))
            and Path(os.fsdecode(arguments[0])).is_absolute()
            and protected(arguments[0])
        ):
            raise RuntimeError("Pilot store guard blocked protected .friday path")

    sys.addaudithook(audit)
    original_connect = sqlite3.connect

    def connect(*args, **kwargs):
        connection = original_connect(*args, **kwargs)

        def authorize(operation, first, _second, _database, _trigger):
            if operation == sqlite3.SQLITE_ATTACH and (
                first is None or protected(first)
            ):
                return sqlite3.SQLITE_DENY
            return sqlite3.SQLITE_OK

        connection.set_authorizer(authorize)
        return connection

    sqlite3.connect = connect
    sqlite3.dbapi2.connect = connect

"""Configure the pinned runner and prevent receipt/capture collisions."""

from __future__ import annotations

import os
import re
import runpy
import sys
from pathlib import Path


def main() -> None:
    scratch = Path(__file__).resolve().parent
    if (
        len(sys.argv) < 3
        or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]*", sys.argv[1]) is None
    ):
        raise SystemExit("Supply a safe receipt name and command")
    requested = sys.argv[1]
    stem = requested
    suffix = 1
    while any(
        (scratch / (stem + extension)).exists() for extension in (".json", ".log")
    ):
        suffix += 1
        stem = f"{requested}-{suffix}"
    reserved = {
        scratch / (name + extension)
        for name in (requested, stem)
        for extension in (".json", ".log")
    }
    reserved.update(
        path.resolve()
        for path in scratch.iterdir()
        if path.suffix.casefold() in (".json", ".log")
    )

    def comparable(path: Path) -> str:
        text = str(path.resolve())
        return text.casefold() if sys.platform == "darwin" else text

    reserved_names = {comparable(path) for path in reserved}
    for argument in sys.argv[2:]:
        if argument.startswith("--") and "=" in argument:
            value = argument.split("=", 1)[1]
        elif (
            argument.startswith("-")
            and not argument.startswith("--")
            and len(argument) > 2
        ):
            value = argument[2:].removeprefix("=")
        else:
            value = argument
        if not value.startswith("-") and comparable(Path(value)) in reserved_names:
            raise SystemExit("Command argument collides with a runner receipt path")
    sys.argv[1] = stem
    # A unique basetemp prevents pytest from cleaning unrelated numbered temp
    # directories and keeps every fixture lane inside this diagnostic scratch.
    if "-m" in sys.argv[2:] and "pytest" in sys.argv[2:]:
        if any(argument.startswith("--basetemp") for argument in sys.argv[2:]):
            raise SystemExit("The diagnostic runner owns pytest --basetemp")
        (scratch / "pytest-tmp").mkdir(exist_ok=True)
        sys.argv.extend(["--basetemp", str(scratch / "pytest-tmp" / stem)])
    os.environ["UV_FIND_LINKS"] = str(scratch / "wheelhouse")
    os.environ["UV_NO_INDEX"] = "1"
    os.environ["LITELLM_LOCAL_MODEL_COST_MAP"] = "True"
    runpy.run_path(str(scratch / "run.py"), run_name="__main__")


if __name__ == "__main__":
    main()

import sys, socket, os
sys.dont_write_bytecode=True
_ports=set()
_root=os.environ.get("REVIEW_REPO", "")
_home=os.path.expanduser("~")
_oldbind=socket.socket.bind
def _bind(self,address):
 result=_oldbind(self,address)
 if self.family in (socket.AF_INET,socket.AF_INET6):_ports.add(self.getsockname()[1])
 return result
socket.socket.bind=_bind
def _audit(event,args):
 if event in ("socket.connect","socket.sendto"):
  addr=args[1] if event=="socket.connect" else args[-1]
  if not isinstance(addr,tuple) or addr[0] not in ("localhost","127.0.0.1","::1") or addr[1] not in _ports:raise RuntimeError("Review network guard blocked destination")
 if event=="open":
  try:p=os.fspath(args[0])
  except TypeError:return
  if isinstance(p,str):
   p=os.path.abspath(p)
   if p.startswith(_home+"/.friday/") or p.startswith(_root+"/.friday/"):raise RuntimeError("Review store guard blocked real store")
sys.addaudithook(_audit)

def _ret_extra_audit(event, args):
    if event in ('socket.getaddrinfo', 'socket.gethostbyname', 'socket.gethostbyaddr'):
        if args[0] not in ('localhost', '127.0.0.1', '::1'):
            raise RuntimeError('Retirement DNS guard blocked destination')
    if event == 'socket.bind':
        address = args[1]
        if not isinstance(address, tuple) or address[0] not in ('localhost', '127.0.0.1', '::1'):
            raise RuntimeError('Retirement bind guard blocked destination')
sys.addaudithook(_ret_extra_audit)

